         do id = 0, 0
            do gi = 1, 1
               ic = rc2(gi)
               !$acc atomic update
               jmat(idens, lamk + ic, sigl + id) = jmat(idens, lamk + ic, sigl + id) &
                                            + jcd(1 + ic + 6*id)
            end do
         end do
         do gi = 1, 1
            ic = rc2(gi)
            do ia = 0, 5
               !$acc atomic update
               jmat(idens, mui + ia, lamk + ic) = jmat(idens, mui + ia, lamk + ic) &
                                           + kac(1 + ia + 6*ic)
            end do
         end do
         do id = 0, 0
            do ia = 0, 5
               !$acc atomic update
               jmat(idens, mui + ia, sigl + id) = jmat(idens, mui + ia, sigl + id) &
                                           + kad(1 + ia + 6*id)
            end do
         end do
         do gi = 1, 1
            ic = rc2(gi)
            do ib = 0, 5
               !$acc atomic update
               jmat(idens, nuj + ib, lamk + ic) = jmat(idens, nuj + ib, lamk + ic) &
                                           + kbc(1 + ib + 6*ic)
            end do
         end do
         do id = 0, 0
            do ib = 0, 5
               !$acc atomic update
               jmat(idens, nuj + ib, sigl + id) = jmat(idens, nuj + ib, sigl + id) &
                                           + kbd(1 + ib + 6*id)
            end do
         end do

         end do   ! idens
#endif
         case (4)
            do x = 1, 31
