            v(10,0) = pax*v(5,0) + wpx*v(5,1) &
               + 2.0_dp*oo2z*(v(2,0) - rz*v(2,1))
            v(11,0) = pax*v(8,0) + wpx*v(8,1)
            v(12,0) = pay*v(7,0) + wpy*v(7,1) &
               + 2.0_dp*oo2z*(v(3,0) - rz*v(3,1))
            v(13,0) = paz*v(9,0) + wpz*v(9,1) &
               + 2.0_dp*oo2z*(v(4,0) - rz*v(4,1))
            v(20,0) = qcy*v(5,0) + wqy*v(5,1)
            v(21,0) = pax*v(18,0) + wpx*v(18,1)
            v(22,0) = pax*v(19,0) + wpx*v(19,1)
            v(23,0) = qcy*v(7,0) + wqy*v(7,1) &
               + 2.0_dp*oo2ze*v(3,1)
            v(24,0) = paz*v(18,0) + wpz*v(18,1)
            v(25,0) = qcy*v(9,0) + wqy*v(9,1)
            v(36,0) = pay*v(35,0) + wpy*v(35,1) &
               + 2.0_dp*oo2ze*v(16,1)
            v(26,0) = qcy*v(10,0) + wqy*v(10,1)
            v(28,0) = paz*v(21,0) + wpz*v(21,1)
            v(29,0) = qcy*v(12,0) + wqy*v(12,1) &
               + 3.0_dp*oo2ze*v(7,1)
            v(32,0) = qcy*v(13,0) + wqy*v(13,1)
            v(40,0) = pay*v(36,0) + wpy*v(36,1) &
               + 1.0_dp*oo2z*(v(35,0) - rz*v(35,1)) &
               + 2.0_dp*oo2ze*v(18,1)
            v(42,0) = qcy*v(25,0) + wqy*v(25,1) &
               + 1.0_dp*oo2e*(v(9,0) - re*v(9,1))
            v(1,1) = pref*f(1)
            v(2,1) = pax*v(1,1) + wpx*v(1,0)
            v(3,1) = pay*v(1,1) + wpy*v(1,0)
            v(4,1) = paz*v(1,1) + wpz*v(1,0)
            v(16,1) = qcy*v(1,1) + wqy*v(1,0)
            v(5,1) = pax*v(2,1) + wpx*v(2,0) &
               + 1.0_dp*oo2z*(v(1,1) - rz*v(1,0))
            v(6,1) = pax*v(4,1) + wpx*v(4,0)
            v(7,1) = pay*v(3,1) + wpy*v(3,0) &
               + 1.0_dp*oo2z*(v(1,1) - rz*v(1,0))
            v(9,1) = paz*v(4,1) + wpz*v(4,0) &
               + 1.0_dp*oo2z*(v(1,1) - rz*v(1,0))
            v(18,1) = pay*v(16,1) + wpy*v(16,0) &
               + 1.0_dp*oo2ze*v(1,0)
            v(10,1) = pax*v(5,1) + wpx*v(5,0) &
               + 2.0_dp*oo2z*(v(2,1) - rz*v(2,0))
            v(11,1) = pay*v(6,1) + wpy*v(6,0)
            v(12,1) = pay*v(7,1) + wpy*v(7,0) &
               + 2.0_dp*oo2z*(v(3,1) - rz*v(3,0))
            v(13,1) = paz*v(9,1) + wpz*v(9,0) &
               + 2.0_dp*oo2z*(v(4,1) - rz*v(4,0))
            v(20,1) = qcy*v(5,1) + wqy*v(5,0)
            v(22,1) = qcy*v(6,1) + wqy*v(6,0)
            v(23,1) = qcy*v(7,1) + wqy*v(7,0) &
               + 2.0_dp*oo2ze*v(3,0)
