                                    + 4.0_dp*jfac*sc*dab(1 + ia + 6*ib)
            kac(1 + ia + 6*ic) = kac(1 + ia + 6*ic) &
                                    - kfac*sc*dbd(1 + ib + 6*id)
            kad(1 + ia + 6*id) = kad(1 + ia + 6*id) &
