               ! the ket loop, so its reciprocal is one division per bra
               ! primitive rather than three per primitive QUARTET.
               rzeta = 1.0_dp/zeta
               oo2z = 0.5_dp*rzeta
               do kq = offcd + 1, offcd + ncd
                  eta = pp_p(kq)
                  zpe = zeta + eta
