                  f(3) = 5.0_dp*f(2)*(0.5_dp*btt)
                  f(4) = 7.0_dp*f(3)*(0.5_dp*btt)
                  f(5) = 9.0_dp*f(4)*(0.5_dp*btt)
                  f(6) = 11.0_dp*f(5)*(0.5_dp*btt)
